import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { getDeliveryById, assignDriver } from "../api/deliveryApi";

interface Delivery {
  id: string;
  orderId: string;
  customerName: string;
  address: string;
  status: string;
  driverId?: string;
  latitude: number;
  longitude: number;
}

export default function DeliveryDetails() {
  const { id } = useParams<{ id: string }>();
  const [delivery, setDelivery] = useState<Delivery | null>(null);
  const [driverId, setDriverId] = useState("");

  useEffect(() => {
    if (id) {
      getDeliveryById(id).then((res) => {
        setDelivery(res.data);
      });
    }
  }, [id]);

  const handleAssign = async () => {
    if (id && driverId) {
      await assignDriver(id, driverId);
      alert("Driver assigned successfully!");
      // Refresh data
      const res = await getDeliveryById(id);
      setDelivery(res.data);
    }
  };

  if (!delivery) {
    return <div>Loading...</div>;
  }

  return (
    <div>
      <h2>Delivery Details</h2>
      <p><strong>Order ID:</strong> {delivery.orderId}</p>
      <p><strong>Customer Name:</strong> {delivery.customerName}</p>
      <p><strong>Address:</strong> {delivery.address}</p>
      <p><strong>Status:</strong> {delivery.status}</p>
      <p><strong>Driver ID:</strong> {delivery.driverId || "Not assigned"}</p>

      <div style={{ marginTop: "20px" }}>
        <input
          type="text"
          placeholder="Enter Driver ID"
          value={driverId}
          onChange={(e) => setDriverId(e.target.value)}
        />
        <button onClick={handleAssign}>Assign Driver</button>
      </div>
    </div>
  );
}
